import { createTestContext } from '../../../../test-utils'
import { Diagnostic, path } from '@servicenow/sdk-build-core'

describe('ExitLoop and SkipIteration Diagnostics', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    describe('ExitLoop - Loop Placement Validation', () => {
        test('should error when ExitLoop is outside any loop construct', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'exitloop-outside-loop.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Flow, wfa } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['test_flow'],
        name: 'Test Flow',
    },
    undefined,
    () => {
        // Invalid: ExitLoop not inside any loop
        wfa.flowLogic.exitLoop({ $id: Now.ID['exit'] })
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const error = diagnostics.find(
                (d) => d.message === 'Exit Loop must be used within a Do Until or For Each loop'
            )
            expect(error).toBeDefined()
            expect(error?.level).toBe(Diagnostic.Level.Error)
        })

        test('should error when ExitLoop is in If but not in loop', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'exitloop-in-if-not-loop.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Flow, wfa } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['test_flow'],
        name: 'Test Flow',
    },
    undefined,
    () => {
        wfa.flowLogic.if({ $id: Now.ID['if'], condition: 'true' }, () => {
            // Invalid: ExitLoop inside If but not inside loop
            wfa.flowLogic.exitLoop({ $id: Now.ID['exit'] })
        })
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const error = diagnostics.find(
                (d) => d.message === 'Exit Loop must be used within a Do Until or For Each loop'
            )
            expect(error).toBeDefined()
            expect(error?.level).toBe(Diagnostic.Level.Error)
        })

        test('should NOT error when ExitLoop is inside ForEach', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'exitloop-in-foreach.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Flow, wfa } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['test_flow'],
        name: 'Test Flow',
    },
    undefined,
    () => {
        wfa.flowLogic.forEach(
            ['item1', 'item2', 'item3'],
            { $id: Now.ID['foreach'] },
            (item) => {
                // Valid: ExitLoop inside ForEach
                wfa.flowLogic.exitLoop({ $id: Now.ID['exit'] })
            }
        )
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const error = diagnostics.find((d) => d.message.includes('Exit Loop must be used within'))
            expect(error).toBeUndefined()
        })

        test('should NOT error when ExitLoop is inside nested ForEach', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'exitloop-nested-foreach.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Flow, wfa } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['test_flow'],
        name: 'Test Flow',
    },
    undefined,
    () => {
        wfa.flowLogic.forEach(
            ['a', 'b'],
            { $id: Now.ID['outer_foreach'] },
            (item) => {
                wfa.flowLogic.if({ $id: Now.ID['if'], condition: 'true' }, () => {
                    wfa.flowLogic.forEach(
                        ['1', '2'],
                        { $id: Now.ID['inner_foreach'] },
                        (innerItem) => {
                            // Valid: ExitLoop finds nearest loop parent
                            wfa.flowLogic.exitLoop({ $id: Now.ID['exit'] })
                        }
                    )
                })
            }
        )
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const error = diagnostics.find((d) => d.message.includes('Exit Loop must be used within'))
            expect(error).toBeUndefined()
        })
    })

    describe('SkipIteration - Loop Placement Validation', () => {
        test('should error when SkipIteration is outside any loop construct', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'skip-outside-loop.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Flow, wfa } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['test_flow'],
        name: 'Test Flow',
    },
    undefined,
    () => {
        // Invalid: SkipIteration not inside any loop
        wfa.flowLogic.skipIteration({ $id: Now.ID['skip'] })
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const error = diagnostics.find(
                (d) => d.message === 'Skip Iteration must be used within a Do Until or For Each loop'
            )
            expect(error).toBeDefined()
            expect(error?.level).toBe(Diagnostic.Level.Error)
        })

        test('should error when SkipIteration is in If but not in loop', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'skip-in-if-not-loop.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Flow, wfa } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['test_flow'],
        name: 'Test Flow',
    },
    undefined,
    () => {
        wfa.flowLogic.if({ $id: Now.ID['if'], condition: 'true' }, () => {
            // Invalid: SkipIteration inside If but not inside loop
            wfa.flowLogic.skipIteration({ $id: Now.ID['skip'] })
        })
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const error = diagnostics.find(
                (d) => d.message === 'Skip Iteration must be used within a Do Until or For Each loop'
            )
            expect(error).toBeDefined()
            expect(error?.level).toBe(Diagnostic.Level.Error)
        })

        test('should NOT error when SkipIteration is inside ForEach', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'skip-in-foreach.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Flow, wfa } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['test_flow'],
        name: 'Test Flow',
    },
    undefined,
    () => {
        wfa.flowLogic.forEach(
            ['item1', 'item2', 'item3'],
            { $id: Now.ID['foreach'] },
            (item) => {
                // Valid: SkipIteration inside ForEach
                wfa.flowLogic.skipIteration({ $id: Now.ID['skip'] })
            }
        )
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const error = diagnostics.find((d) => d.message.includes('Skip Iteration must be used within'))
            expect(error).toBeUndefined()
        })

        test('should NOT error when SkipIteration is inside ForEach with conditional', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'skip-with-if.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Flow, wfa } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['test_flow'],
        name: 'Test Flow',
    },
    undefined,
    () => {
        wfa.flowLogic.forEach(
            ['item1', 'item2', 'item3'],
            { $id: Now.ID['foreach'] },
            (item) => {
                wfa.flowLogic.if({ $id: Now.ID['if'], condition: 'item == "skip"' }, () => {
                    // Valid: SkipIteration inside ForEach -> If
                    wfa.flowLogic.skipIteration({ $id: Now.ID['skip'] })
                })
            }
        )
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const error = diagnostics.find((d) => d.message.includes('Skip Iteration must be used within'))
            expect(error).toBeUndefined()
        })
    })
})
